features={pid:feat for pid,feat in cur.execute('SELECT ID, FeatureType FROM PlotFeatures') if feat}
# coast/ocean

def is_water(pid):
    return terrains[pid] in ('TERRAIN_OCEAN','TERRAIN_COAST')

def is_coast(pid):
    return terrains[pid]=='TERRAIN_COAST'

land=[pid for pid,terr in terrains.items() if terr in ('TERRAIN_GRASS','TERRAIN_PLAINS')]
mountains=[pid for pid,terr in terrains.items() if terr=='TERRAIN_GRASS_MOUNTAIN']

# river edges
rivers={}
for pid,ne,w,nw in cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers'):
    if ne or w or nw:
        rivers[pid]={'NE':ne,'W':w,'NW':nw}

# neighbor models

def neighbors_odd_r(x,y):
    if y%2==0:
        return {
            'NE':(x, y-1),
            'E':(x+1, y),
            'SE':(x, y+1),
            'SW':(x-1, y+1),
            'W':(x-1, y),
            'NW':(x-1, y-1),
        }
    else:
        return {
            'NE':(x+1, y-1),
            'E':(x+1, y),
            'SE':(x+1, y+1),
            'SW':(x, y+1),
            'W':(x-1, y),
            'NW':(x, y-1),
        }

def neighbors_even_q(x,y):
    if x%2==0:
        return {
            'NE':(x+1, y-1),
            'E':(x+1, y),
            'SE':(x+1, y+1),
            'SW':(x, y+1),
            'W':(x-1, y),
            'NW':(x, y-1),
        }
    else:
        return {
            'NE':(x, y-1),
            'E':(x+1, y),
            'SE':(x, y+1),
            'SW':(x-1, y+1),
            'W':(x-1, y),
            'NW':(x-1, y-1),
        }

# hex distance conversion for odd-r

def odd_r_to_cube(x,y):
    # https://www.redblobgames.com/grids/hex-grids/#conversions-offset
    col = x - (y - (y&1))//2
    row = y
    # axial (q=col, r=row)
    q=col; r=row
    x3=q; z3=r; y3=-x3-z3
    return (x3,y3,z3)

def even_q_to_cube(x,y):
    # even-q vertical layout
    q=x
    r = y - (x + (x&1))//2
    x3=q; z3=r; y3=-x3-z3
    return (x3,y3,z3)


def hex_dist(cube_a, cube_b):
    return max(abs(cube_a[0]-cube_b[0]), abs(cube_a[1]-cube_b[1]), abs(cube_a[2]-cube_b[2]))

# adjacency compute

def compute_adjacency(model='odd_r', campus_has_district_adj=True, holy_has_district_adj=True):
    if model=='odd_r':
        neighbor_fn=neighbors_odd_r
        to_cube=odd_r_to_cube
    else:
        neighbor_fn=neighbors_even_q
        to_cube=even_q_to_cube

