    river_adj=set()
    for pid,edges in rivers.items():
        x=pid%width; y=pid//width
        neigh=neighbor_fn(x,y)
        for d,has in edges.items():
            if not has:
                continue
            river_adj.add(pid)
            nx,ny=neigh[d]
            if 0<=nx<width and 0<=ny<height:
                river_adj.add(ny*width+nx)

    def adjacents(pid):
        x=pid%width; y=pid//width
        neigh=neighbor_fn(x,y)
        res=[]
        for nx,ny in neigh.values():
            if 0<=nx<width and 0<=ny<height:
                res.append(ny*width+nx)
        return res

    def district_adj_score(district, pid, placements, city_center):
