        adj_pids=adjacents(pid)
        # count adjacency to placed districts and city center
        adjacent_districts=[p for p in adj_pids if p in placements.values() or p==city_center]
        # features
        if district=='CAMPUS':
            for n in adj_pids:
                if terrains[n]=='TERRAIN_GRASS_MOUNTAIN':
                    adj+=1
                if features.get(n)=='FEATURE_REEF':
                    adj+=2
                if features.get(n)=='FEATURE_GEOTHERMAL_FISSURE':
                    adj+=2
                if features.get(n)=='FEATURE_JUNGLE':
                    adj+=1
            if campus_has_district_adj:
                adj+=len(adjacent_districts)
        elif district=='HOLY_SITE':
            for n in adj_pids:
                if terrains[n]=='TERRAIN_GRASS_MOUNTAIN':
                    adj+=1
                if features.get(n) in ('FEATURE_FOREST','FEATURE_JUNGLE'):
                    adj+=1
            if holy_has_district_adj:
                adj+=len(adjacent_districts)
        elif district=='COMMERCIAL_HUB':
            if pid in river_adj:
                adj+=2
            # adjacent harbor special
            for n in adj_pids:
                if placements.get('HARBOR')==n:
                    adj+=2
            # adjacent districts (including city center)
            adj+=len(adjacent_districts)
        elif district=='INDUSTRIAL_ZONE':
            # only district adjacency here
            adj+=len(adjacent_districts)
        elif district=='THEATER_SQUARE':
            adj+=len(adjacent_districts)
        elif district=='HARBOR':
            # +2 if adjacent to city center
            if city_center in adj_pids:
                adj+=2
            # +1 per adjacent district (not counting itself) and maybe? We'll include
            adj+=len(adjacent_districts)
        else:
            pass
        return adj

    # candidate tiles per district
    def candidates_for_district(district):
        if district=='HARBOR':
            return [pid for pid in terrains if is_coast(pid)]
        else:
            return land[:]

    districts=['CAMPUS','HOLY_SITE','COMMERCIAL_HUB','INDUSTRIAL_ZONE','THEATER_SQUARE','HARBOR']

    best=None
    best_detail=None

    # precompute cubes for distance
    cube_cache={pid: to_cube(pid%width, pid//width) for pid in terrains}

    for city_center in land:
        # set workable range 3
        center_cube=cube_cache[city_center]
        workable=set(pid for pid in terrains if hex_dist(center_cube, cube_cache[pid])<=3)
        # candidate tile per district within range and valid
        dist_candidates={d:[pid for pid in candidates_for_district(d) if pid in workable and pid!=city_center] for d in districts}
        # choose 3 districts combos
        for dist_combo in combinations(districts,3):
            # quick candidate list; if any district has no candidates, skip
            if any(len(dist_candidates[d])==0 for d in dist_combo):
                continue
            # iterate placements (cartesian product) but avoid overlaps
            # brute force: might be large but land small
            # We'll do nested loops
            for pid1 in dist_candidates[dist_combo[0]]:
                for pid2 in dist_candidates[dist_combo[1]]:
                    if pid2==pid1: continue
                    for pid3 in dist_candidates[dist_combo[2]]:
                        if pid3 in (pid1,pid2): continue
                        placements={dist_combo[0]:pid1, dist_combo[1]:pid2, dist_combo[2]:pid3}
                        # compute adjacency for each district based on placements
                        total=0
                        scores={}
                        for d in dist_combo:
                            scores[d]=district_adj_score(d, placements[d], placements, city_center)
                            total+=scores[d]
                        if best is None or total>best:
                            best=total
                            best_detail=(city_center, dist_combo, placements, scores)
    return best, best_detail

for model in ['odd_r','even_q']:
    best, detail = compute_adjacency(model=model, campus_has_district_adj=True, holy_has_district_adj=True)
    print('model',model,'best',best)
    city_center, combo, placements, scores = detail
    print('center',city_center, (city_center%width, city_center//width))
    print('combo',combo)
    print('placements', {k:(v%width,v//width) for k,v in placements.items()})
    print('scores',scores)
